function render(t, api) {
  // 1. infected body cell: viruses multiply; MHC class I shows their peptide on the surface
  el.vir.forEach((v, i) => { const s = i < 2 ? 1 : api.seg(t, 300 + i * 250, 800 + i * 250, "back_out");
    api.set(v, {opacity: (s * (1 - api.seg(t, 5200, 5800))).toFixed(3)}); });
  el.mhcL.forEach((m, i) => api.set(m, {opacity: (api.seg(t, 900 + i * 120, 1300 + i * 120) * (1 - api.seg(t, 5200, 5800))).toFixed(3)}));
  R.fade(api, el.cVir, t, 400, 800, 2000, 2300);
  R.fade(api, el.cMhc, t, 1100, 1500, 4300, 4600);
  // 2. the killer T cell glides in and docks; in the lens its receptors grip MHC class I
  const d = api.seg(t, 2400, 3500, "ease_out");
  api.set(el.tc, {transform: `translate(${api.lerp(START[0], DOCK[0], d).toFixed(1)} ${api.lerp(START[1], DOCK[1], d).toFixed(1)})`, opacity: api.seg(t, 2300, 2700).toFixed(3)});
  api.set(el.tcHalo, {opacity: (api.seg(t, 3500, 3900) * (0.35 + 0.15 * Math.sin(t / 200))).toFixed(3)});
  api.set(el.k, {transform: `translate(0 ${(-180 * (1 - api.seg(t, 2500, 3700, "ease_out"))).toFixed(1)})`});
  R.fade(api, el.cT, t, 2800, 3200);
  // 3. perforin punches pores, granzymes enter; the target cell breaks up
  const P = api.seg(t, 4700, 5100);
  el.perf.forEach((o) => { const f = api.seg(t, 4700 + o.i * 80, 5300 + o.i * 80, "ease_in"), gr = el.gran[o.i % 3], px = o.i % 2 ? 483 : 417;
    at(api, o.g, api.lerp(gr[0], px + (o.i % 3 - 1) * 4, f), api.lerp(gr[1] + 14, memT(px) - 2, f), P * (1 - api.seg(t, 5300 + o.i * 80, 5500 + o.i * 80))); });
  el.pores.forEach((p) => api.set(p, {opacity: api.seg(t, 5100, 5400).toFixed(3)}));
  el.gz.forEach((o) => { const px = o.i % 2 ? 483 : 417, f = api.seg(t, 5300 + o.i * 120, 6100 + o.i * 120, "ease_out");
    at(api, o.g, px + (o.i - 2.5) * 6 * f, memT(px) - 10 + f * (40 + (o.i % 3) * 14), api.seg(t, 5300 + o.i * 120, 5450 + o.i * 120)); });
  api.set(el.tgtDim, {opacity: (0.45 * api.seg(t, 5600, 6400)).toFixed(3)});
  // left: the infected cell shrinks into fragments
  const b = api.seg(t, 5200, 6200, "ease_in_out");
  api.set(el.bc, {opacity: (1 - b).toFixed(3)});
  el.frag.forEach((o) => at(api, o.g, TX + o.dx * (0.8 + 0.35 * b), TY + o.dy * (0.8 + 0.35 * b), b));
  R.fade(api, el.cPerf, t, 4900, 5300);
  R.fade(api, el.cAns, t, 4800, 5200);
}
